// Generated from polar-h10-metrics; do not edit by hand.
window.PolarMetricCatalog = Object.freeze([{"id":"raw_ecg","streamSuffix":"rawECG","label":"Raw ECG","detail":"Unfiltered H10 voltage samples · 130 Hz","unit":"µV","category":"Raw signals","explainer":"The H10 exposes a single-lead ECG-like voltage waveform. It is useful for waveform inspection and independent processing, but this research stream is not a diagnostic 12-lead ECG.","evidence":"device signal","citationLabel":"Smital et al. (2020)","citationUrl":"https://consensus.app/papers/details/ad2a724fefd55d25baee823438fc672e/?utm_source=unknown","keywords":"raw voltage waveform electrocardiogram","raw":true,"normalizable":false,"channels":1,"rateHz":130.0,"streamType":"ECG","formula":"y(t) = ECG(t) [µV]; x-axis = sensor time t","formulaTemplate":"ecg","formulaSource":"ecg"},{"id":"raw_acc","streamSuffix":"rawACC","label":"Raw accelerometer","detail":"X, Y and Z · 200 Hz","unit":"mg","category":"Raw signals","explainer":"Three-axis chest acceleration contains body motion, posture and small breathing-related movements. Motion strongly confounds respiratory inference, so downstream users should retain the raw axes for quality control.","evidence":"device signal","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"raw movement acceleration x y z","raw":true,"normalizable":false,"channels":3,"rateHz":200.0,"streamType":"Accelerometer","formula":"a(t) = [x(t), y(t), z(t)] [mg]","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"raw_force","streamSuffix":"rawForce","label":"Raw Go Direct force","detail":"Verified GDX-RB Force (N) · 10 Hz preferred, metadata fallback","unit":"N","category":"Raw signals","explainer":"The Go Direct force channel is forwarded as measured by the Vernier device. Notification batches are preserved and intra-batch timestamps use the configured sample period.","evidence":"protocol interoperability","citationLabel":"Vernier Go Direct examples","citationUrl":"https://github.com/VernierST/godirect-examples","keywords":"vernier go direct respiration belt force newton raw","raw":true,"normalizable":false,"channels":1,"rateHz":0.0,"streamType":"RespirationForce","formula":"F(t) = Go Direct force measurement [N]","formulaTemplate":null,"formulaSource":"ecg"},{"id":"acc_magnitude","streamSuffix":"accMagnitude","label":"3D acceleration magnitude","detail":"Euclidean magnitude of X, Y and Z","unit":"g","category":"Raw signals","explainer":"Acceleration magnitude is √(x²+y²+z²), expressed in g. It removes orientation sign but combines gravity, body movement and breathing motion, so it is a signal feature rather than a specific physiological measure.","evidence":"signal feature","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"movement motion magnitude activity","raw":false,"normalizable":true,"channels":1,"rateHz":200.0,"streamType":"AccelerometerMetric","formula":"|a(t)| = √(x(t)² + y(t)² + z(t)²) / 1000","formulaTemplate":"sqrt(x*x + y*y + z*z) / 1000","formulaSource":"accelerometer"},{"id":"ecg_mean","streamSuffix":"ecgMean","label":"ECG window mean","detail":"Five-second rolling mean","unit":"µV","category":"ECG features","explainer":"The rolling mean estimates the local DC offset of the single-lead waveform. Changes can reflect baseline wander or electrode/contact effects and should not be interpreted as cardiac morphology.","evidence":"signal-quality aid","citationLabel":"Smital et al. (2020)","citationUrl":"https://consensus.app/papers/details/ad2a724fefd55d25baee823438fc672e/?utm_source=unknown","keywords":"ecg baseline offset mean quality","raw":false,"normalizable":true,"channels":1,"rateHz":2.0,"streamType":"ECGMetric","formula":"μECG(t) = (1/N) Σ ECGᵢ over the preceding 5 s","formulaTemplate":"moving_mean(ecg, 5)","formulaSource":"ecg"},{"id":"ecg_rms","streamSuffix":"ecgRms","label":"ECG RMS amplitude","detail":"Five-second root-mean-square amplitude","unit":"µV","category":"ECG features","explainer":"RMS summarizes overall waveform energy within the rolling window. It is useful for monitoring amplitude and gross signal changes, but it is not a validated diagnosis or a direct measure of cardiac effort.","evidence":"signal-quality aid","citationLabel":"Smital et al. (2020)","citationUrl":"https://consensus.app/papers/details/ad2a724fefd55d25baee823438fc672e/?utm_source=unknown","keywords":"ecg energy amplitude rms quality","raw":false,"normalizable":true,"channels":1,"rateHz":2.0,"streamType":"ECGMetric","formula":"RMS(t) = √[(1/N) Σ ECGᵢ²] over the preceding 5 s","formulaTemplate":"moving_rms(ecg, 5)","formulaSource":"ecg"},{"id":"ecg_peak_to_peak","streamSuffix":"ecgPeakToPeak","label":"ECG peak-to-peak","detail":"Five-second maximum minus minimum","unit":"µV","category":"ECG features","explainer":"Peak-to-peak amplitude is the largest voltage excursion in the rolling window. It helps reveal clipping, motion spikes and changing contact, but it is highly sensitive to artifacts.","evidence":"signal-quality aid","citationLabel":"Smital et al. (2020)","citationUrl":"https://consensus.app/papers/details/ad2a724fefd55d25baee823438fc672e/?utm_source=unknown","keywords":"ecg range clipping artifact quality","raw":false,"normalizable":true,"channels":1,"rateHz":2.0,"streamType":"ECGMetric","formula":"P2P(t) = max(ECGᵢ) − min(ECGᵢ) over the preceding 5 s","formulaTemplate":"moving_max(ecg, 5) - moving_min(ecg, 5)","formulaSource":"ecg"},{"id":"ecg_sd","streamSuffix":"ecgSd","label":"ECG standard deviation","detail":"Five-second sample standard deviation","unit":"µV","category":"ECG features","explainer":"Standard deviation describes dispersion around the local ECG mean. Like RMS, it can support signal-quality inspection but does not isolate a particular ECG wave or clinical condition.","evidence":"signal-quality aid","citationLabel":"Smital et al. (2020)","citationUrl":"https://consensus.app/papers/details/ad2a724fefd55d25baee823438fc672e/?utm_source=unknown","keywords":"ecg variability standard deviation quality","raw":false,"normalizable":true,"channels":1,"rateHz":2.0,"streamType":"ECGMetric","formula":"sECG(t) = √[Σ(ECGᵢ − μECG)² / (N − 1)] over 5 s","formulaTemplate":"moving_std(ecg, 5)","formulaSource":"ecg"},{"id":"heart_rate","streamSuffix":"heartRate","label":"Heart rate","detail":"H10 device-derived beat rate","unit":"bpm","category":"Heart rate","explainer":"Heart rate is the number of cardiac cycles per minute reported by the sensor. It responds to activity, posture, temperature, emotion and many other influences, so context is essential.","evidence":"established measure","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"pulse bpm cardiac beats","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HeartRate","formula":"HR(t) = device-reported beats per minute","formulaTemplate":"hr","formulaSource":"heartRate"},{"id":"rr_interval","streamSuffix":"rrInterval","label":"RR interval","detail":"Accepted beat-to-beat interval","unit":"ms","category":"Heart rate","explainer":"An RR interval is the elapsed time between consecutive detected heartbeats. Clean normal-to-normal intervals are the input to HRV calculations; ectopic beats and detection artifacts can distort every derived metric.","evidence":"established measure","citationLabel":"Laborde, Mosley & Thayer (2017)","citationUrl":"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2017.00213/full","keywords":"ibi nn beat interval heartbeat","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"RR","formula":"RRᵢ = t(Rᵢ) − t(Rᵢ₋₁)","formulaTemplate":"rr","formulaSource":"rrInterval"},{"id":"mean_nn","streamSuffix":"meanNN","label":"Mean NN interval","detail":"Five-minute accepted RR mean","unit":"ms","category":"Heart rate","explainer":"Mean NN is the average accepted normal-to-normal interval in the analysis window. It is inversely related to mean heart rate, while preserving interval units used by HRV methods.","evidence":"established measure","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"mean rr ibi nn average","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"meanNN = (1/N) Σ NNᵢ over the accepted 5 min window","formulaTemplate":"rr_mean(rr, 300)","formulaSource":"rrInterval"},{"id":"mean_heart_rate","streamSuffix":"meanHeartRate","label":"Mean heart rate","detail":"60,000 divided by mean NN","unit":"bpm","category":"Heart rate","explainer":"Mean heart rate is calculated from the mean accepted NN interval over the current window. It smooths beat-to-beat changes and should not be confused with the sensor's latest instantaneous value.","evidence":"established measure","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"mean average bpm rolling","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"meanHR = 60,000 / meanNN","formulaTemplate":"rr_mean_hr(rr, 300)","formulaSource":"rrInterval"},{"id":"rmssd","streamSuffix":"rmssd","label":"RMSSD","detail":"Five-minute successive-difference HRV","unit":"ms","category":"HRV & relaxation","explainer":"RMSSD is the root mean square of successive NN-interval differences and emphasizes short-term beat-to-beat variability. It is commonly used as a vagally mediated HRV index, but respiration, posture, artifacts and individual context still matter.","evidence":"well-established HRV","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"hrv vagal parasympathetic recovery relaxation","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"RMSSD = √[(1/(N−1)) Σ(NNᵢ₊₁ − NNᵢ)²]","formulaTemplate":"rr_rmssd(rr, 300)","formulaSource":"rrInterval"},{"id":"ln_rmssd","streamSuffix":"lnRMSSD","label":"lnRMSSD","detail":"Natural logarithm of RMSSD","unit":"ln(ms)","category":"HRV & relaxation","explainer":"lnRMSSD is the natural-log transform of RMSSD, used because raw RMSSD is often right-skewed. It improves comparability in statistical work but retains RMSSD's physiological and measurement limitations.","evidence":"well-established transform","citationLabel":"Laborde, Mosley & Thayer (2017)","citationUrl":"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2017.00213/full","keywords":"hrv log vagal recovery statistics","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"lnRMSSD = ln(RMSSD)","formulaTemplate":"rr_ln_rmssd(rr, 300)","formulaSource":"rrInterval"},{"id":"sdnn","streamSuffix":"sdnn","label":"SDNN","detail":"Five-minute NN sample standard deviation","unit":"ms","category":"HRV & relaxation","explainer":"SDNN is the standard deviation of accepted NN intervals and summarizes total variability present in the chosen window. Its meaning depends strongly on recording length, so values from unlike window durations should not be compared directly.","evidence":"well-established HRV","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"hrv total variability autonomic","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"SDNN = √[Σ(NNᵢ − meanNN)² / (N−1)]","formulaTemplate":"rr_sdnn(rr, 300)","formulaSource":"rrInterval"},{"id":"pnn50","streamSuffix":"pNN50","label":"pNN50","detail":"Successive NN differences over 50 ms","unit":"%","category":"HRV & relaxation","explainer":"pNN50 is the percentage of adjacent accepted NN pairs that differ by more than 50 ms. It correlates with RMSSD and vagally mediated variability, although RMSSD is usually preferred and pNN50 depends on age and sampling context.","evidence":"established HRV","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"hrv vagal successive differences percentage","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"pNN50 = 100 · count(|NNᵢ₊₁ − NNᵢ| > 50 ms) / (N−1)","formulaTemplate":"rr_pnn50(rr, 300)","formulaSource":"rrInterval"},{"id":"sd1","streamSuffix":"sd1","label":"Poincaré SD1","detail":"RMSSD divided by √2","unit":"ms","category":"HRV & relaxation","explainer":"SD1 is the short-axis dispersion of the Poincaré plot and describes short-term beat-to-beat variability. For the standard calculation it is mathematically RMSSD/√2, so selecting both does not provide independent information.","evidence":"well-established HRV","citationLabel":"Shaffer & Ginsberg (2017)","citationUrl":"https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2017.00258/full","keywords":"hrv poincare short term vagal","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"HRV","formula":"SD1 = RMSSD / √2","formulaTemplate":"rr_sd1(rr, 300)","formulaSource":"rrInterval"},{"id":"coherence","streamSuffix":"coherence","label":"Normalized coherence","detail":"Peak-band power divided by total power","unit":"0–1","category":"Coherence","explainer":"This app-specific score is the fraction of RR spectral power concentrated around the dominant 0.04–0.26 Hz peak. Slow breathing near cardiorespiratory resonance can increase narrow-band oscillation, but the score is not a direct measure of emotion, health or relaxation.","evidence":"algorithmic spectral index","citationLabel":"Sévoz-Couche & Laborde (2022)","citationUrl":"https://www.sciencedirect.com/science/article/abs/pii/S0149763422000653","keywords":"coherence resonance breathing hrv spectral","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"coherence = peak-band RR power / total RR power","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"coherence_confidence","streamSuffix":"coherenceConfidence","label":"Coherence confidence","detail":"Window coverage and sample readiness","unit":"0–1","category":"Coherence","explainer":"Confidence reports whether the coherence window has enough accepted RR data and near-complete time coverage. It describes computational readiness, not confidence that a psychological interpretation is true.","evidence":"quality indicator","citationLabel":"Polar Stream legacy formula inventory","citationUrl":"https://github.com/GeorgeFejer91/Polar-Stream/blob/main/docs/metric-evidence.md","keywords":"coherence quality readiness coverage","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"confidence = 0.55·sample readiness + 0.45·window coverage","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"heartmath_coherence","streamSuffix":"heartMathCoherence","label":"HeartMath-style coherence ratio","detail":"(peak power ÷ remaining power)²","unit":"ratio","category":"Coherence","explainer":"This reproduces the legacy HeartMath-style formula: the squared ratio of power in a 0.03 Hz peak window to remaining 0.0033–0.4 Hz power. It quantifies spectral concentration and is exposed for compatibility; it is not a validated clinical relaxation score.","evidence":"legacy/proprietary-inspired","citationLabel":"Sévoz-Couche & Laborde (2022)","citationUrl":"https://www.sciencedirect.com/science/article/abs/pii/S0149763422000653","keywords":"heartmath coherence ratio peak power legacy","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"HeartMath ratio = [peak-band power / (total power − peak-band power)]²","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"coherence_peak_frequency","streamSuffix":"coherencePeakFrequency","label":"Coherence peak frequency","detail":"Dominant RR spectral peak","unit":"Hz","category":"Coherence","explainer":"Peak frequency is the strongest RR-variability oscillation between 0.04 and 0.26 Hz. A value near 0.1 Hz can occur during slow paced breathing and resonance, but frequency alone does not establish why the oscillation occurred.","evidence":"spectral feature","citationLabel":"Sévoz-Couche & Laborde (2022)","citationUrl":"https://www.sciencedirect.com/science/article/abs/pii/S0149763422000653","keywords":"coherence resonance frequency breathing","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"fpeak = argmax P(f), 0.04 ≤ f ≤ 0.26 Hz","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"coherence_peak_power","streamSuffix":"coherencePeakPower","label":"Coherence peak-band power","detail":"Integrated power ±0.015 Hz around peak","unit":"ms²","category":"Coherence","explainer":"Peak-band power integrates the RR spectrum in a 0.03 Hz window centered on the dominant coherence peak. Its absolute scale depends on preprocessing and windowing, so comparisons require identical settings.","evidence":"spectral feature","citationLabel":"Sévoz-Couche & Laborde (2022)","citationUrl":"https://www.sciencedirect.com/science/article/abs/pii/S0149763422000653","keywords":"coherence power spectrum peak band","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"Ppeak = ∫ P(f)df from fpeak−0.015 to fpeak+0.015 Hz","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"coherence_total_power","streamSuffix":"coherenceTotalPower","label":"Coherence total power","detail":"Integrated RR power from 0.0033–0.4 Hz","unit":"ms²","category":"Coherence","explainer":"Total power integrates the RR spectrum across the legacy 0.0033–0.4 Hz analysis band. It supplies the denominator for the normalized score and is not by itself a specific sympathetic or parasympathetic measure.","evidence":"spectral feature","citationLabel":"Billman (2013)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/23431279/","keywords":"coherence total power spectrum hrv","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Coherence","formula":"Ptotal = ∫ P(f)df from 0.0033 to 0.4 Hz","formulaTemplate":null,"formulaSource":"rrInterval"},{"id":"acc_breathing_magnitude","streamSuffix":"accBreathingMagnitude","label":"ACC breathing magnitude estimate","detail":"Smoothed principal-axis chest-motion projection","unit":"g","category":"Breathing","explainer":"This continuous curve is a smoothed projection of selected accelerometer axes, not lung volume or airflow. It can preserve timing for exploratory breath-rate analysis, but this H10-specific estimate is unvalidated and is strongly confounded by movement, posture, strap placement and axis choice.","evidence":"unvalidated experimental estimate","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"acc breath respiration magnitude waveform projection experimental","raw":false,"normalizable":true,"channels":1,"rateHz":20.0,"streamType":"Breathing","formula":"b(t) = smoothed projection of selected ACC axes onto the calibrated principal axis","formulaTemplate":"breathing_magnitude(x, y, z, true, false, true, 0.75, false, false)","formulaSource":"accelerometer"},{"id":"breathing_volume","streamSuffix":"breathingVolume","label":"ACC breathing waveform","detail":"Calibrated chest-motion projection","unit":"0–1","category":"Breathing","explainer":"The waveform projects smoothed chest acceleration onto a calibrated principal movement axis and rescales it between observed quantile bounds. Chest accelerometers can capture breathing motion, but this H10-specific algorithm has not been validated as lung volume and is vulnerable to body movement.","evidence":"experimental estimate","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath respiration waveform volume chest","raw":false,"normalizable":true,"channels":1,"rateHz":20.0,"streamType":"Breathing","formula":"volume(t) = clamp[(b(t)−q₀.₀₅)/(q₀.₉₅−q₀.₀₅), 0, 1]","formulaTemplate":"breathing_magnitude(x, y, z, true, false, true, 0.75, true, false)","formulaSource":"accelerometer"},{"id":"breathing_signal_confidence","streamSuffix":"breathingSignalConfidence","label":"ACC breathing signal confidence","detail":"Range, motion, coverage, and periodicity quality index","unit":"0–1","category":"Breathing","explainer":"Confidence summarizes whether the calibrated H10 chest-motion projection is strong, recent, relatively periodic, and not dominated by broadband movement. It is an app-specific signal-quality index rather than a probability of physiological correctness, and low values should cause downstream analyses to reject or flag the waveform.","evidence":"experimental quality indicator","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath respiration waveform signal confidence quality motion periodicity","raw":false,"normalizable":false,"channels":1,"rateHz":20.0,"streamType":"Breathing","formula":"confidence = rangeQuality · motionQuality · (0.4 + 0.6·coverage·periodicity)","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breathing_signal_ready","streamSuffix":"breathingSignalReady","label":"ACC breathing signal ready","detail":"Calibration, freshness, and motion gate","unit":"0/1","category":"Breathing","explainer":"Ready becomes one only after principal-axis calibration while samples are fresh and the short-term movement score remains acceptable. It is a processing-readiness flag, not evidence that the waveform equals airflow or lung volume.","evidence":"experimental readiness indicator","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath respiration waveform ready calibration freshness motion gate","raw":false,"normalizable":false,"channels":1,"rateHz":20.0,"streamType":"Breathing","formula":"ready = calibrated ∧ fresh ∧ motionQuality ≥ 0.35","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breathing_phase","streamSuffix":"breathingPhase","label":"Breath phase classifier","detail":"+1 inhale · −1 exhale · 0 pause or not ready","unit":"class","category":"Breathing","explainer":"Phase classifies the calibrated ACC waveform velocity into three public states: inhale, exhale, or pause/not ready. Its threshold is normalized per second from the accepted ACC sample count so BLE batch size does not change the classification scale. It remains an unvalidated motion classification rather than airflow; movement, posture, strap placement and axis choice can obscure or reverse the inferred phase.","evidence":"unvalidated experimental classification","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"inhale exhale pause phase respiration classifier experimental","raw":false,"normalizable":false,"channels":1,"rateHz":20.0,"streamType":"Breathing","formula":"phase(t) = threshold[(volume(t)−volume(t−Δt))/Δt]; {−1,0,+1}","formulaTemplate":"breathing_phase(x, y, z, true, false, true, 0.75, 0.60, false)","formulaSource":"accelerometer"},{"id":"breathing_calibration","streamSuffix":"breathingCalibration","label":"Breathing calibration","detail":"Principal-axis calibration progress","unit":"0–1","category":"Breathing","explainer":"Calibration progress reports how much of the initial ACC calibration interval has been observed. A completed interval does not guarantee a clean respiratory signal; sufficient chest-motion range is also required.","evidence":"quality indicator","citationLabel":"Polar Stream legacy formula inventory","citationUrl":"https://github.com/GeorgeFejer91/Polar-Stream/blob/main/docs/metric-evidence.md","keywords":"breath calibration readiness quality","raw":false,"normalizable":false,"channels":1,"rateHz":4.0,"streamType":"Breathing","formula":"progress(t) = collected calibration samples / required samples","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breathing_axis_range","streamSuffix":"breathingAxisRange","label":"Breathing axis range","detail":"Calibrated 5th–95th percentile travel","unit":"g","category":"Breathing","explainer":"Axis range is the robust movement span used to scale the ACC-derived waveform. A very small span suggests weak signal, while a large span may reflect breathing or unrelated movement.","evidence":"signal-quality aid","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath movement range quality calibration","raw":false,"normalizable":true,"channels":1,"rateHz":4.0,"streamType":"Breathing","formula":"axisRange = q₀.₉₅(b) − q₀.₀₅(b)","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breathing_rate","streamSuffix":"breathingRate","label":"Breathing rate","detail":"60 divided by mean peak-to-peak interval","unit":"breaths/min","category":"Breathing","explainer":"Breathing rate is estimated from successive like-polarity extrema in the ACC-derived waveform. It becomes available only after accepted cycles and can be unreliable during movement or irregular shallow breathing.","evidence":"experimental estimate","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"respiratory rate rpm breaths minute","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Breathing","formula":"rate = 60 / mean(same-polarity extremum intervals)","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breathing_dynamics_confidence","streamSuffix":"breathingDynamicsConfidence","label":"Breathing-dynamics confidence","detail":"Accepted-breath count and freshness","unit":"0–1","category":"Breathing dynamics","explainer":"Confidence increases as accepted respiratory cycles accumulate toward the legacy 200-breath target. It expresses data sufficiency and freshness, not certainty about a clinical or emotional state.","evidence":"quality indicator","citationLabel":"Polar Stream legacy formula inventory","citationUrl":"https://github.com/GeorgeFejer91/Polar-Stream/blob/main/docs/metric-evidence.md","keywords":"breath entropy quality readiness confidence","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"confidence = clamp(max(Ninterval,Namplitude) / 200, 0, 1)","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_mean","streamSuffix":"breathIntervalMean","label":"Breath interval mean","detail":"Mean like-polarity extremum interval","unit":"s","category":"Breathing dynamics","explainer":"Mean breath interval averages the time between successive peaks or successive troughs. Its reciprocal gives breathing rate, while variability around it is retained in separate dynamics metrics.","evidence":"experimental ACC adaptation","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath interval duration mean","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"μI = (1/N) Σ intervalᵢ","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_sd","streamSuffix":"breathIntervalSD","label":"Breath interval SD","detail":"Sample standard deviation of intervals","unit":"s","category":"Breathing dynamics","explainer":"Interval SD measures absolute dispersion in detected respiratory-cycle duration. More variability is not inherently better or worse; artifacts, tasks and genuine adaptive variation can all increase it.","evidence":"experimental ACC adaptation","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath interval variability standard deviation","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"sI = √[Σ(intervalᵢ−μI)²/(N−1)]","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_cv","streamSuffix":"breathIntervalCV","label":"Breath interval CV","detail":"Interval SD divided by mean","unit":"ratio","category":"Breathing dynamics","explainer":"The coefficient of variation divides interval SD by the absolute interval mean, making dispersion less dependent on scale. It is descriptive and should not be interpreted as a standalone marker of respiratory health.","evidence":"experimental ACC adaptation","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath interval coefficient variation normalized","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"CVI = sI / |μI|","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_acw50","streamSuffix":"breathIntervalACW50","label":"Breath interval ACW50","detail":"First autocorrelation lag below 0.5","unit":"breaths","category":"Breathing dynamics","explainer":"ACW50 is the first lag where autocorrelation drops below 0.5, summarizing how long interval patterns remain similar. It is a time-series memory descriptor, not a direct measure of relaxation or pathology.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath autocorrelation memory dynamics","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"ACW50 = first lag k where autocorr(interval,k) < 0.5","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_psd_slope","streamSuffix":"breathIntervalPsdSlope","label":"Breath interval PSD slope","detail":"Low-frequency log–log spectral slope","unit":"slope","category":"Breathing dynamics","explainer":"PSD slope summarizes how interval-series power changes with frequency after detrending and standardization. It is an exploratory scaling feature whose value depends on record length and implementation choices.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath spectrum slope fractal dynamics","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"slope = OLS slope of log power on log frequency in the low-frequency interval spectrum","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_lzc","streamSuffix":"breathIntervalLZC","label":"Breath interval Lempel–Ziv","detail":"Median-binarized normalized complexity","unit":"0–1","category":"Breathing dynamics","explainer":"Lempel–Ziv complexity counts new binary patterns after thresholding intervals around their mean. Higher values indicate less compressible sequences in this encoding, not automatically healthier or more adaptive breathing.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath lempel ziv irregularity complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"LZC = normalized Lempel–Ziv phrase count of mean-binarized intervals","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_sampen","streamSuffix":"breathIntervalSampEn","label":"Breath interval sample entropy","detail":"m=2 · r=0.2 SD · delay 1","unit":"entropy","category":"Breathing dynamics","explainer":"Sample entropy estimates the unpredictability of interval patterns by comparing matches of length m and m+1. Values depend on sample count and parameter choices; short or artifact-contaminated series are unstable.","evidence":"established method, experimental input","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath sample entropy irregularity complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"SampEn = −ln(A/B), m=2, r=0.2·SD, delay=1","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_interval_mse","streamSuffix":"breathIntervalMSE","label":"Breath interval multiscale entropy","detail":"Entropy AUC across scales 1–5","unit":"entropy AUC","category":"Breathing dynamics","explainer":"Multiscale entropy aggregates sample entropy after coarse-graining the interval series across several scales. It aims to capture complexity beyond one time scale, but needs substantial clean data and is not a diagnostic score here.","evidence":"established method, experimental input","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath multiscale entropy complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"MSE = trapezoidal AUC of SampEn across coarse-graining scales 1…5","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_mean","streamSuffix":"breathAmplitudeMean","label":"Breath amplitude mean","detail":"Mean alternating peak-to-trough excursion","unit":"0–1","category":"Breathing dynamics","explainer":"Mean amplitude averages accepted peak-to-trough excursions in the normalized ACC waveform. Because the waveform is wearer- and calibration-specific, this is relative chest movement rather than tidal volume.","evidence":"experimental ACC adaptation","citationLabel":"Schipper et al. (2021)","citationUrl":"https://pubmed.ncbi.nlm.nih.gov/33739305/","keywords":"breath amplitude depth excursion","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"μA = (1/N) Σ |peakᵢ − troughᵢ|","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_sd","streamSuffix":"breathAmplitudeSD","label":"Breath amplitude SD","detail":"Sample standard deviation of excursions","unit":"0–1","category":"Breathing dynamics","explainer":"Amplitude SD measures dispersion in accepted normalized chest-motion excursions. Movement artifacts and changing posture can alter it, so it should be inspected alongside the raw ACC and confidence.","evidence":"experimental ACC adaptation","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude variability standard deviation","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"sA = √[Σ(amplitudeᵢ−μA)²/(N−1)]","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_cv","streamSuffix":"breathAmplitudeCV","label":"Breath amplitude CV","detail":"Amplitude SD divided by mean","unit":"ratio","category":"Breathing dynamics","explainer":"Amplitude CV expresses excursion variability relative to mean excursion. It supports within-protocol comparison but has no universal threshold for relaxation or respiratory health.","evidence":"experimental ACC adaptation","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude coefficient variation","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"CVA = sA / |μA|","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_acw50","streamSuffix":"breathAmplitudeACW50","label":"Breath amplitude ACW50","detail":"First autocorrelation lag below 0.5","unit":"breaths","category":"Breathing dynamics","explainer":"Amplitude ACW50 reports how many breaths the amplitude pattern remains autocorrelated above 0.5. It describes temporal persistence and does not assign that persistence a positive or negative meaning.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude autocorrelation memory","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"ACW50 = first lag k where autocorr(amplitude,k) < 0.5","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_psd_slope","streamSuffix":"breathAmplitudePsdSlope","label":"Breath amplitude PSD slope","detail":"Low-frequency log–log spectral slope","unit":"slope","category":"Breathing dynamics","explainer":"This slope summarizes low-frequency scaling in the detrended amplitude sequence. It is exploratory and especially sensitive to accepted-cycle count, outliers and the selected spectral estimator.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude spectral slope dynamics","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"slope = OLS slope of log power on log frequency in the low-frequency amplitude spectrum","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_lzc","streamSuffix":"breathAmplitudeLZC","label":"Breath amplitude Lempel–Ziv","detail":"Mean-binarized normalized complexity","unit":"0–1","category":"Breathing dynamics","explainer":"Lempel–Ziv complexity measures how compressible the binarized sequence of breath amplitudes is. It is an algorithmic irregularity feature and should not be equated with emotional flexibility without a validated protocol.","evidence":"exploratory complexity","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude lempel ziv complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"LZC = normalized Lempel–Ziv phrase count of mean-binarized amplitudes","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_sampen","streamSuffix":"breathAmplitudeSampEn","label":"Breath amplitude sample entropy","detail":"m=2 · r=0.2 SD · delay 1","unit":"entropy","category":"Breathing dynamics","explainer":"Sample entropy estimates pattern unpredictability in successive normalized breath amplitudes. It requires enough accepted cycles and can become undefined when patterns are too short or too uniform.","evidence":"established method, experimental input","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude sample entropy complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"SampEn = −ln(A/B), m=2, r=0.2·SD, delay=1","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"breath_amplitude_mse","streamSuffix":"breathAmplitudeMSE","label":"Breath amplitude multiscale entropy","detail":"Entropy AUC across scales 1–5","unit":"entropy AUC","category":"Breathing dynamics","explainer":"Multiscale entropy summarizes amplitude-sequence unpredictability across coarse-grained scales. This adaptation uses ACC-derived excursions rather than a validated respiratory belt signal, so interpretation remains exploratory.","evidence":"established method, experimental input","citationLabel":"Bará et al. (2024)","citationUrl":"https://consensus.app/papers/details/de562a29bb8454eda201852b544fd9d7/?utm_source=unknown","keywords":"breath amplitude multiscale entropy complexity","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"BreathingDynamics","formula":"MSE = trapezoidal AUC of SampEn across coarse-graining scales 1…5","formulaTemplate":null,"formulaSource":"accelerometer"},{"id":"excitement_score","streamSuffix":"excitementScore","label":"Excite-O-Meter excitement score","detail":"1 − mean[Φ(zRR), Φ(zRMSSD)] · live provisional","unit":"0–1","category":"Excitation (experimental)","explainer":"This reproduces the open-source Excite-O-Meter equation: independently standardized RR interval and rolling 10-beat RMSSD are converted through the standard-normal CDF, averaged, and subtracted from one. The source method is retrospective; this live stream uses session-to-date population statistics after a 10-pair baseline, so values are provisional and are not a validated measure of emotion or clinical arousal.","evidence":"legacy experimental formula","citationLabel":"Excite-O-Meter source implementation","citationUrl":"https://github.com/luisqtr/exciteometer/blob/main/docs/1_UserManual.md#scientific-disclaimer","keywords":"excite o meter excitement score arousal legacy percentile cdf rr rmssd","raw":false,"normalizable":false,"channels":1,"rateHz":0.0,"streamType":"Experimental","formula":"score = 1 − [Φ(zRR) + Φ(zRMSSD₁₀)] / 2","formulaTemplate":"excitement(rr, 300)","formulaSource":"rrInterval"},{"id":"excitometer","streamSuffix":"excitometer","label":"Activation composite (experimental)","detail":"Within-session HR ↑ plus lnRMSSD ↓","unit":"0–1","category":"Excitation (experimental)","explainer":"The excitometer is an explicitly experimental within-session composite: 65% standardized heart-rate elevation plus 35% standardized lnRMSSD reduction, mapped through a logistic curve. HRV can covary with stress, but no single H10-only score uniquely identifies sympathetic arousal, excitement or emotion.","evidence":"unvalidated composite","citationLabel":"Immanuel et al. (2023)","citationUrl":"https://consensus.app/papers/details/14838ea9a9045710b4a676dbb7d595aa/?utm_source=unknown","keywords":"excitation activation arousal stress experimental","raw":false,"normalizable":true,"channels":1,"rateHz":0.0,"streamType":"Experimental","formula":"activation = logistic[0.65·z(HR) − 0.35·z(lnRMSSD)]","formulaTemplate":"sigmoid(0.65*zscore_n(60000/rr, 20) - 0.35*zscore_n(rr_ln_rmssd(rr, 300), 20))","formulaSource":"rrInterval"}]);
